<?php
require 'config.php'; require 'functions.php'; require_officer();
$posts=$pdo->query("SELECT a.*,u.name author,u.role author_role,(SELECT COUNT(*) FROM announcement_upvotes x WHERE x.announcement_id=a.id) upvotes,(SELECT COUNT(*) FROM announcement_acknowledgments x WHERE x.announcement_id=a.id) member_acknowledgments FROM announcements a JOIN users u ON u.id=a.author_id ORDER BY a.is_pinned DESC,a.created_at DESC,a.id DESC")->fetchAll();
$reports=$pdo->query("SELECT * FROM reports ORDER BY created_at DESC LIMIT 30")->fetchAll();
$users = is_admin() ? $pdo->query("SELECT id,name,email,role FROM users ORDER BY name")->fetchAll() : [];
?>
