<header class="top"><div><strong>CS3B : Bulletin</strong><span>Officer Dashboard</span></div><nav><a href="./">View Site</a><a href="officers">Officers</a><a href="profile">My Profile</a><a href="change-password">Change Password</a><a href="logout">Logout</a></nav></header><main class="container"><div class="dashhead"><div><p class="eyebrow"><?=e(role_label(user_role()))?></p><h1>Dashboard</h1></div><a class="primary button" href="announcement-form">+ New Announcement</a></div>
