<?php if(is_admin()): ?><h2>Officer Accounts</h2><div class="tablewrap"><table><tr><th>Name</th><th>Login email</th><th>Role</th><th>Recovery</th></tr><?php foreach($users as $account): ?><tr><td><?=e($account['name'])?></td><td><?=e($account['email'])?></td><td><?=e(role_label($account['role']))?></td><td><form method="post" action="reset-password" onsubmit="return confirm('Restore this account to its initial password?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="user_id" value="<?=$account['id']?>"><button class="upvote" type="submit">Restore initial password</button></form></td></tr><?php endforeach; ?></table></div><?php endif; ?>
<h2>Recent Reports & Concerns</h2><div class="tablewrap"><table><tr><th>Type</th><th>Subject</th><th>Email</th><th>Status</th><th>Action</th></tr><?php foreach($reports as $r): ?><tr><td><?=e($r['type'])?></td><td><?=e($r['subject'])?></td><td><?=e($r['email'])?></td><td><?=e($r['status'])?></td><td><a href="report?id=<?=$r['id']?>">View</a></td></tr><?php endforeach; ?></table></div>
